INSERT INTO `jurnal_guru` VALUES (363, 248, 57, 'Amy Safitri', 11, 21, 'IPAS', '', '', '', '28-07-2025', '16:48:24', '10:45', '12:45', 'Peserta didik mempelajari salah satu contoh perubahan energi dari energi cahaya menjadi energi kimia, yaitu proses fotosintesis. Kemudian, peserta didik mengerjakan LKPD guna menumbuhkan pemahaman mereka lebih dalam mengenai proses fotosintesis.', 'BAB 1. Perubahan Bentuk Energi', 1, '28-07-2025', 'Ganjil', 90, '2025/2026', '52785e21-4fac-4348-ae75-9bcfc9268d03');
INSERT INTO `jurnal_guru` VALUES (364, 251, 57, 'Amy Safitri', 11, 16, 'Pendidikan Pancasila', '', '', '', '28-07-2025', '16:58:57', '13:30', '15:00', 'Peserta didik mempelajari tentang cara menghargai keberagaman agama dan kepercayaan yang ada di sekitar. Kemudian untuk menambah pemahaman secara mendalam, mereka mengerjakan LKS yang berkaitan dengan keberagaman agama di suatu lingkungan.', 'BAB 1. Mengenal Lingkungan Sekitar', 1, '28-07-2025', 'Ganjil', 90, '2025/2026', 'fc3e3d1d-82cf-4150-b15b-6d8d1104c3dd');
