INSERT INTO `jurnal_guru` VALUES (10822, 923, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '20-07-2026', '16:47:16', '12:00', '13:00', 'Murid mengetahui urutan sistem pencernaan', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '25-08-2026', 'Ganjil', 91, '2026/2027', '89611df1-f4e4-480e-95a7-df08361726d8');
INSERT INTO `jurnal_guru` VALUES (10823, 922, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '20-07-2026', '16:48:59', '08:15', '08:45', 'Murid belajar tentang fungsi tiap organ pencernaan, meliputi: mulut, kerongkongan, lambung, hati, kantong empedu, pankreas, usus halus, usus besar dan anus.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '25-08-2026', 'Ganjil', 91, '2026/2027', '8c6fd965-2e1c-434f-adf8-b803de05978f');
INSERT INTO `jurnal_guru` VALUES (10824, 924, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '20-07-2026', '16:49:41', '14:00', '15:00', 'Murid mengerjakan LKPD dengan menuliskan fungsi tiap organ pencernaan, mulai dari mulut hingga anus.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '25-08-2026', 'Ganjil', 91, '2026/2027', '2aa6cac4-736a-457c-9cec-1d6d64b15728');
INSERT INTO `jurnal_guru` VALUES (10825, 917, 57, 'Amy Safitri, S.Pd', 37, 15, 'Matematika', '', '', '', '21-07-2026', '16:52:30', '08:15', '10:35', 'Kegiatan belajar diawali dengan murid merefleksikan kembali perkalian 1-100.\r\nKemudian merefleksikan bilangan pecahan.\r\nLalu murid belajar tentang perkalian bilangan asli dengan pecahan, pecahan dengan bilangan asli serta menyederhanakan bentuk pecahan.\r\n', 'BAB 1. Pecahan dan Desimal', 1, '25-08-2026', 'Ganjil', 91, '2026/2027', '433fcd41-6fa3-4218-9e3e-48ae96fcbcb5');
INSERT INTO `jurnal_guru` VALUES (10826, 996, 57, 'Amy Safitri, S.Pd', 37, 25, 'life skill', '', '', '', '24-07-2026', '16:57:01', '08:45', '10:15', 'Murid membuat rencana kegiatan yang akan mereka lakukan saat akhir pekan.\r\nmurid mendapatkan tugas membuat video tentang kegiatan mereka diakhir pekan, sesuai dnegan jadwal yang telah mereka buat.', 'Membuat Jadwal Harian', 1, '25-08-2026', 'Ganjil', 91, '2026/2027', '46206b7d-7bc4-4671-9989-99e943d54182');
