INSERT INTO `jurnal_guru` VALUES (12160, 924, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '28-09-2026', '20:54:04', '14:00', '15:00', 'Hari Pertama kegiatan Asesmen Akhir Semester. Peserta didik membuat proyek \"Infografis Sistem Pencernaan\" yang didalamnya ada integrasi mata pelajaran IPAS, Al-Islam, Bahasa Jawa dan Seni Rupa.', 'ATS', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '4ae81b5c-76c0-44b6-96a7-db1ed8bb0fc8');
