INSERT INTO `jurnal_guru` VALUES (12162, 923, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '28-09-2026', '20:54:26', '12:00', '13:00', 'Hari Pertama kegiatan Asesmen Akhir Semester. Peserta didik membuat proyek \"Infografis Sistem Pencernaan\" yang didalamnya ada integrasi mata pelajaran IPAS, Al-Islam, Bahasa Jawa dan Seni Rupa.', 'ATS', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'eace334a-4033-4b59-868d-2791d0e70f93');
INSERT INTO `jurnal_guru` VALUES (12163, 996, 57, 'Amy Safitri, S.Pd', 37, 25, 'life skill', '', '', '', '25-09-2026', '20:54:58', '08:45', '10:15', 'Persiapan kegiatan pembuatan proyek untuk ATS.', '', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'a8901acb-edc5-48de-b062-cf0f2863896c');
INSERT INTO `jurnal_guru` VALUES (12164, 921, 57, 'Amy Safitri, S.Pd', 37, 3, 'Bahasa Jawa', '', '', '', '24-09-2026', '20:57:13', '12:00', '13:00', 'Peserta didik mengerjakan soal tentang unggah ungguh basa di LKS, meliputi:\r\n1. Menentukan jenis basa yang digunakan\r\n2. Mengubah krama alus menjadi ngoko lugu\r\n3. Mengubah Ngoko lugu menjadi Ngoko alus', 'BAB 1. Unggah Ungguh Basa', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '3902a3bd-617e-48b0-b6d9-75212d191acd');
INSERT INTO `jurnal_guru` VALUES (12165, 920, 57, 'Amy Safitri, S.Pd', 37, 16, 'Pendidikan Pancasila', '', '', '', '24-09-2026', '20:58:39', '08:15', '09:45', 'Peserta didik secara berkelompok dengan teman sebangku melakukan wawancara kepasa ustadz/ustadzah di sekolah. Mereka mencari informasi terkait pengamalan pancasila yang telah dilakukan ustadz/ustadzah selama di sekolah. Kemudian peserta didik mengaitkanny', 'BAB 1. Hubungan antar nilai pancasila', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '5687d756-0bcd-451b-b889-cf70fc3c2d6c');
INSERT INTO `jurnal_guru` VALUES (12166, 1079, 57, 'Amy Safitri, S.Pd', 37, 7, 'Bahasa Indonesia', '', '', '', '23-09-2026', '20:59:44', '08:15', '09:35', 'Peserta didik mengerjakan sumatif BAB 1 di LKS, yaitu tentang teks eksplanasi.', 'BAB 1. Teks Eksplanasi', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'd803b302-2e13-4103-a690-bca8e8cde24f');
INSERT INTO `jurnal_guru` VALUES (12167, 1080, 57, 'Amy Safitri, S.Pd', 37, 20, 'Seni Rupa', '', '', '', '23-09-2026', '21:01:52', '09:35', '10:35', 'Peserta didik membuat batik dengan menggunakan prinsip pola dan ritme. Mereka meilih salah satu motif batik yang telah disediakan. Lalu menggambarkannya secara berulang sehingga menjadi sebuah gambar batik.', 'BAB 2. Menggambar Ritme dalam Seni Rupa', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '70b7cb5f-3874-4e2f-b1c4-fdf517e668a7');
INSERT INTO `jurnal_guru` VALUES (12168, 917, 57, 'Amy Safitri, S.Pd', 37, 15, 'Matematika', '', '', '', '22-09-2026', '21:03:24', '08:15', '10:35', 'Peserta didik mengerjakan soal dengan cara mencongak. Materi soal meliputi perkalian pecahan, pembagian pecahan dan bilangan desimal.', 'BAB 1. Pecahan dan Desimal', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'f3d55067-326e-41a2-9140-09bd0a47c1c7');
INSERT INTO `jurnal_guru` VALUES (12169, 924, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '21-09-2026', '21:04:01', '14:00', '15:00', 'Peserta didik mengerjakan latihan soal BAB 1 di LKS bersama guru.', 'BAB 1. Pecahan dan Desimal', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '5e111638-e5c1-445b-8b3d-3d0dde8348be');
INSERT INTO `jurnal_guru` VALUES (12170, 922, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '21-09-2026', '21:04:54', '08:15', '08:45', 'Peserta didik secara berkelompok bermain kuis sistem pencernaan dengan menggunakan Quizziz. Penilaian kelompok berdasarkan perolehan poin tertinggi.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'd1476f1a-0081-4411-af08-8522e43e6a03');
INSERT INTO `jurnal_guru` VALUES (12171, 923, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '21-09-2026', '21:05:42', '12:00', '13:00', 'Peserta didik secara berkelompok bermain kuis sistem pencernaan dengan menggunakan Quizziz. Penilaian kelompok berdasarkan perolehan poin tertinggi.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'e103c52a-121e-4120-83d3-cf2222d1391f');
INSERT INTO `jurnal_guru` VALUES (12172, 921, 57, 'Amy Safitri, S.Pd', 37, 3, 'Bahasa Jawa', '', '', '', '17-09-2026', '21:10:29', '12:00', '13:00', 'Peserta didik secara berkelompok membuat teks informasi dengan menggunakan pilihan topik yang telah disediakan. Pilihan topik meiputi, sapi, alun-alun lumajang, gunung semeru dan tari tradisional.', 'BAB 1. Teks Informasi', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '3dfde562-7d63-406d-bf69-b9b0c0a6b11a');
INSERT INTO `jurnal_guru` VALUES (12173, 917, 57, 'Amy Safitri, S.Pd', 37, 15, 'Matematika', '', '', '', '15-09-2026', '21:11:44', '08:15', '10:35', 'Peserta didi belajar tentang mengubah bilangan pecahan menjadi bilangan desimal. Kemudian membandingkan bilangan dasimal, dilanjut dengan mengurutkan bilangan desimal.', 'BAB 1. Pecahan dan Desimal', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '31346dc9-2223-4e25-ab35-505cd95553e6');
INSERT INTO `jurnal_guru` VALUES (12174, 922, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '14-09-2026', '21:13:01', '08:15', '08:45', 'Peserta didik melanjutkan presentasi kelompok tentang studi kasus gangguan sistem pencernaan.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '3e7ebdb1-370a-4ab9-8014-1034a91ecb44');
