INSERT INTO `jurnal_guru` VALUES (12176, 923, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '14-09-2026', '21:14:03', '12:00', '13:00', 'Peserta didik melakukan penilaian harian sumatif BAB 1.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '669f22d6-6254-4f79-b37b-e485819672ef');
INSERT INTO `jurnal_guru` VALUES (12177, 996, 57, 'Amy Safitri, S.Pd', 37, 25, 'life skill', '', '', '', '11-09-2026', '21:16:29', '08:45', '10:15', 'Peserta didik mengetahui tentang tingkatan suhu yang digunakan untuk menyetrika sesuai dnegan jenis kain.', 'Menyetrika', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'cfc779bd-1578-42b9-b025-3027577e5e3a');
INSERT INTO `jurnal_guru` VALUES (12178, 920, 57, 'Amy Safitri, S.Pd', 37, 16, 'Pendidikan Pancasila', '', '', '', '10-09-2026', '21:18:18', '08:15', '09:45', 'Peserta didik mengerjakan LKPD tentang menganalisis kalimat  dna menentukan 2 sila yang berhubungan. Mereka menganalisis 48 kalimat.', 'BAB 1. Hubungan antar nilai pancasila', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '3984fe99-fede-42a5-bb23-c6501c8fd9bb');
INSERT INTO `jurnal_guru` VALUES (12179, 1080, 57, 'Amy Safitri, S.Pd', 37, 20, 'Seni Rupa', '', '', '', '09-09-2026', '21:22:59', '09:35', '10:35', 'Peserta didik menggambar 4 macam gambar yang menggunakan 1 atau lebih jenis ritme.', 'BAB 2. Menggambar Ritme dalam Seni Rupa', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', 'b155fde9-b052-4dd0-90a6-1fe8ab7e6e61');
INSERT INTO `jurnal_guru` VALUES (12180, 922, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '07-09-2026', '21:29:03', '08:15', '08:45', 'Peserta didik bersama guru mengulas materi tentang sistem pencernaan dna makanan bergizi. Kemudian, peserta didik dibagi menjadi 7 kelompok, guna mengerjakan kasus tentang gangguan sistem pencernaan.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '8483c6db-c1c2-47f5-9bad-fba0438205ed');
INSERT INTO `jurnal_guru` VALUES (12181, 923, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '07-09-2026', '21:30:23', '12:00', '13:00', 'Peserta didik bekerja sama dnegan kelompok masing-masing untuk mengerjakan kasus yang berbeda-beda. Mulai dari kasus tentang sariawan, dispepsia, gastritis, GERD, diare, sembelit dan diabetes melitus.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '00bbd478-33f6-4309-b3c0-1870d6eb3302');
INSERT INTO `jurnal_guru` VALUES (12182, 924, 57, 'Amy Safitri, S.Pd', 37, 21, 'IPAS', '', '', '', '07-09-2026', '21:30:58', '14:00', '15:00', 'Peserta didik bersama kelompok mempresentasikan hasil pemecahan kasus tentang gangguan sistem pencernaan.', 'BAB 1. Makanan Bergizi untuk Kesehatan Pencernaanmu', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '2ee03063-e20d-4a69-9161-bdc36bda62ce');
