INSERT INTO `jurnal_guru` VALUES (12184, 920, 57, 'Amy Safitri, S.Pd', 37, 16, 'Pendidikan Pancasila', '', '', '', '03-09-2026', '21:33:01', '08:15', '09:45', 'Peserta didik secara berkelompok dengan teman sebangku, memecahkan sebuah kasus yang berkaitan dengan pengamalan antar sila-sila pancasila. Kasus yang tersedia tentnag kerja kelompok dna bakti sosial.', 'BAB 1. Hubungan antar nilai pancasila', 1, '29-09-2026', 'Ganjil', 91, '2026/2027', '89cf9cf3-7e62-4c1b-ba66-200899342651');
